const params    = JSON.parse($input.first().json.input);
const principal = parseFloat(params.principal);
const rate      = parseFloat(params.rate);
const years     = parseFloat(params.years);

const finalAmount = principal * Math.pow(1 + rate, years);
const interest    = finalAmount - principal;

return `Monto final: $${Math.round(finalAmount).toLocaleString('es-CO')} COP. Intereses generados: $${Math.round(interest).toLocaleString('es-CO')} COP.`;

const body = $input.item.json.body;
const msg = body.message || '';

// Detectar idioma
const hasSpanishChars = ['á','é','í','ó','ú','ñ','ü','¿','¡'].some(c => msg.includes(c));
const spanishWords = ['cuánto','cómo','qué','dónde','cuándo','pesos','invertir','tasa','dólar','años','está','tengo','quiero','puedo'];
const msgLower = msg.toLowerCase();
const hasSpanishWords = spanishWords.some(w => msgLower.includes(w));
const englishWords = ['what','how much','invest','exchange rate','current','dollar','years','interest'];
const hasEnglishWords = englishWords.some(w => msgLower.includes(w));

let idioma;
if (hasSpanishChars || hasSpanishWords) {
  idioma = 'SPANISH';
} else if (hasEnglishWords) {
  idioma = 'ENGLISH';
} else {
  idioma = 'SPANISH';
}

// Limitar historial a 3 si hay imagen (evitar exceder context window)
const limite = body.image ? 3 : 7;
const mensajes = (body.messages || []).slice(-limite);
const historial = mensajes.length > 0
  ? mensajes.map(m => (m.role === 'user' ? 'Usuario' : 'FinBot') + ': ' + m.content).join('\n') + '\n\n'
  : '';

// chatInput SIEMPRE es solo texto - imagen va separada
return {
  chatInput: '[RESPOND IN ' + idioma + ' ONLY]\n\n' + historial + msg,
  image:     body.image || null,
  mode:      body.mode  || 'text',
  idioma:    idioma
};

const content = $json.choices[0].message.content;
const cleaned = content.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();

let response, toolUsed;

try {
  const parsed = JSON.parse(cleaned);
  // Si tiene el formato estándar
  if (parsed.response) {
    response = parsed.response;
    toolUsed = parsed.tool_used || 'imagen';
  } else {
    // Si devolvió otro JSON, convertirlo a texto descriptivo
    response = JSON.stringify(parsed);
    toolUsed = 'imagen';
  }
} catch(e) {
  response = cleaned;
  toolUsed = 'imagen';
}

return { response, tool_used: toolUsed };

const output  = $input.first().json.output;
const cleaned = output.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
const parsed  = JSON.parse(cleaned);
return { response: parsed.response, tool_used: parsed.tool_used || null };

const chatInput = $input.first().json.chatInput;
const image = $input.first().json.image;

return {
  chatInput: chatInput,
  image: image,
  body: JSON.stringify({
    model: "gpt-4o-mini",
    messages: [
      {
        role: "system",
        content: "Eres FinBot, asistente financiero. Analiza la imagen y responde en el idioma del usuario. DEBES responder ÚNICAMENTE con este JSON exacto sin ningún texto adicional: {\"response\": \"tu respuesta descriptiva completa aquí\", \"tool_used\": \"imagen\"}. No uses markdown, no uses bloques de código, solo el JSON."
      },
      {
        role: "user",
        content: [
          { type: "text", text: chatInput },
          { type: "image_url", image_url: { url: image } }
        ]
      }
    ]
  })
};
